"use client";

import React, { useState } from "react";
import { ShieldAlert, ArrowRight } from "lucide-react";

export function AdminImpersonationBanner() {
  const [active, setActive] = useState(true);

  if (!active) return null;

  return (
    <div className="w-full max-w-2xl bg-amber-500/10 border border-amber-500/20 p-4 rounded-xl shadow-lg select-none font-sans text-foreground flex flex-col sm:flex-row items-center justify-between gap-3 relative overflow-hidden">
      <div className="absolute inset-0 bg-gradient-to-r from-amber-500/5 to-transparent pointer-events-none" />

      <div className="flex items-center gap-2.5 relative z-10">
        <div className="p-2 rounded-lg bg-amber-500/15 border border-amber-500/20 text-amber-400">
          <ShieldAlert className="w-4 h-4 animate-pulse" />
        </div>
        <div className="text-xs">
          <h4 className="font-black leading-none mb-1 text-amber-300">Active Impersonation Session</h4>
          <p className="text-[10px] text-muted-foreground/60">Viewing workspace details as <span className="font-bold text-foreground">Jane Doe</span>.</p>
        </div>
      </div>

      <button 
        onClick={() => setActive(false)}
        className="px-3.5 py-1.5 bg-amber-600 hover:bg-amber-500 text-white text-[10px] font-extrabold rounded-lg flex items-center gap-1 transition-all relative z-10"
      >
        <span>Exit Impersonation</span>
        <ArrowRight className="w-3 h-3" />
      </button>
    </div>
  );
}
